    if type(new_rate) is not int or new_rate<=0 or approval.get('allow') is not True or approval.get('client_id')!=client or type(approval.get('maximum_rate')) is not int or new_rate>approval['maximum_rate']:raise ValueError('literal client quota approval and finite fairness budget required')
    before=_rate(bootstrap,client)
